                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            objects.append((color, cells))

    # The two shapes of each color exchange positions, flipping vertically.
    out = [[0] * w for _ in range(h)]
    by_color = {}
    for color, cells in objects:
        by_color.setdefault(color, []).append(cells)

    for color, group in by_color.items():
        if len(group) != 2:
            for cells in group:
                for r, c in cells:
                    out[r][c] = color
            continue
        a, b = group
        for source, target in ((a, b), (b, a)):
            sr, sc = min(r for r, c in source), min(c for r, c in source)
            tr, tc = min(r for r, c in target), min(c for r, c in target)
            height = max(r for r, c in source) - sr
            for r, c in source:
                out[tr + height - (r - sr)][tc + (c - sc)] = color
    return out
